-- ---------------------------------------------------------------------------
-- טפשת — phase 16: 296 more names, "ignore if it already exists".
--
-- Run once in the Supabase SQL Editor, after phase 15.
--
-- The uniqueness check this needs used to be a partial index on
-- (text) where family_id is null — that column, and therefore that index,
-- no longer exist after phase 13 removed the Family feature. This adds a
-- plain unique constraint on `text` instead (every name is a flat
-- catalogue entry now, no family scoping left to key off of), then imports
-- with ON CONFLICT (text) DO NOTHING — an existing name is left completely
-- untouched, not updated, per "ignore it".
--
-- Two real gaps in this batch's own data, imported honestly rather than
-- guessed:
--   - syllables, popularity, and popularity_score are empty for all 296
--     rows in the source file — every row gets NULL for these three.
--   - 135 of the 296 rows are missing origin, meaning_he, meaning_source,
--     and meaning_confidence together — same story, NULL rather than
--     invented. Those 135 names will show no meaning text on their cards
--     until that data is supplied later.
-- ---------------------------------------------------------------------------

alter table public.names
  add constraint names_text_unique unique (text);

